import 'package:flutter/material.dart';import 'api.dart';import 'catalog.dart';
class CartItem{final Product product;final String size,color;int quantity;CartItem(this.product,this.size,this.color,{this.quantity=1});double get total=>product.price*quantity;}
class CartStore extends ChangeNotifier{CartStore._();static final instance=CartStore._();final List<CartItem> items=[];void add(Product p,String s,String c){final i=items.indexWhere((x)=>x.product.id==p.id&&x.size==s&&x.color==c);if(i>=0)items[i].quantity++;else items.add(CartItem(p,s,c));notifyListeners();}void change(CartItem x,int d){x.quantity+=d;if(x.quantity<=0)items.remove(x);notifyListeners();}double get subtotal=>items.fold(0,(s,x)=>s+x.total);void clear(){items.clear();notifyListeners();}}
class CartPage extends StatelessWidget{const CartPage({super.key});@override Widget build(BuildContext context)=>SafeArea(child:AnimatedBuilder(animation:CartStore.instance,builder:(context,_){final c=CartStore.instance;if(c.items.isEmpty)return const Center(child:Text('Корзина пуста',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold)));return Column(children:[const Padding(padding:EdgeInsets.all(16),child:Align(alignment:Alignment.centerLeft,child:Text('Корзина',style:TextStyle(fontSize:28,fontWeight:FontWeight.bold)))),Expanded(child:ListView.builder(itemCount:c.items.length,itemBuilder:(context,i){final x=c.items[i];return ListTile(title:Text(x.product.name),subtitle:Text('${x.size} • ${x.color} • ${x.product.price.toStringAsFixed(0)} с.'),trailing:Row(mainAxisSize:MainAxisSize.min,children:[IconButton(onPressed:()=>c.change(x,-1),icon:const Icon(Icons.remove)),Text('${x.quantity}'),IconButton(onPressed:()=>c.change(x,1),icon:const Icon(Icons.add))]));})),Padding(padding:const EdgeInsets.all(16),child:SizedBox(width:double.infinity,child:FilledButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const CheckoutPage())),child:Text('Оформить • ${c.subtotal.toStringAsFixed(0)} сомони'))))]);}));}
class CheckoutPage extends StatefulWidget{const CheckoutPage({super.key});@override State<CheckoutPage> createState()=>_CheckoutPageState();}class _CheckoutPageState extends State<CheckoutPage>{String delivery='Courier';@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Оформление заказа')),body:ListView(padding:const EdgeInsets.all(18),children:[RadioListTile(value:'Courier',groupValue:delivery,onChanged:(v)=>setState(()=>delivery=v!),title:const Text('Доставка курьером')),RadioListTile(value:'Pickup',groupValue:delivery,onChanged:(v)=>setState(()=>delivery=v!),title:const Text('Самовывоз')),if(delivery=='Courier')const TextField(decoration:InputDecoration(labelText:'Адрес доставки',border:OutlineInputBorder())),const SizedBox(height:20),FilledButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>PaymentPage(delivery:delivery))),child:const Text('Продолжить к оплате'))]));}
class PaymentPage extends StatefulWidget{final String delivery;const PaymentPage({super.key,required this.delivery});@override State<PaymentPage> createState()=>_PaymentPageState();}class _PaymentPageState extends State<PaymentPage>{String method='DADO Wallet';bool busy=false;Future<void> submit()async{setState(()=>busy=true);try{final c=CartStore.instance;final result=await ApiClient.instance.createOrder({'deliveryMethod':widget.delivery,'paymentMethod':method,'items':c.items.map((x)=>{'productId':x.product.id,'productName':x.product.name,'variant':'${x.size}/${x.color}','quantity':x.quantity,'unitPrice':x.product.price}).toList()});c.clear();if(mounted)Navigator.pushAndRemoveUntil(context,MaterialPageRoute(builder:(_)=>OrderSuccessPage(number:result['number']?.toString()??'')),(r)=>r.isFirst);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Оплата')),body:ListView(padding:const EdgeInsets.all(18),children:[for(final m in ['DADO Wallet','Банковская карта','QR-оплата','Наличными'])RadioListTile(value:m,groupValue:method,onChanged:(v)=>setState(()=>method=v!),title:Text(m)),FilledButton(onPressed:busy?null:submit,child:Padding(padding:const EdgeInsets.all(14),child:busy?const CircularProgressIndicator():Text('Создать заказ • ${CartStore.instance.subtotal.toStringAsFixed(0)} сомони'))),const SizedBox(height:10),const Text('Оплата картой/QR будет считаться завершенной только после подтвержденного сервером webhook эквайринга.',style:TextStyle(fontSize:12,color:Colors.black54))]));}
class OrderSuccessPage extends StatelessWidget{final String number;const OrderSuccessPage({super.key,required this.number});@override Widget build(BuildContext context)=>Scaffold(body:Center(child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.check_circle,size:90,color:Colors.green),const Text('Заказ создан',style:TextStyle(fontSize:28,fontWeight:FontWeight.bold)),Text(number),const Text('Статус оплаты будет обновлен сервером.')])));}
